add(50,1,'DIKW','주문 기록을 집계해 “금요일 매출이 다른 요일보다 20% 높다”는 사실을 얻었다. DIKW에서 이 결과가 가장 직접적으로 해당하는 단계는?', ['정보(Information)','데이터(Data)','지식(Knowledge)','지혜(Wisdom)'], '단순한 주문 기록은 데이터이고, 맥락과 관계를 부여해 의미를 얻으면 정보가 된다. 이를 일반화해 규칙을 이해하면 지식, 의사결정에 활용하면 지혜로 이어진다.');
add(50,1,'데이터 웨어하우스','기업 전체의 장기간 데이터를 통합해 의사결정을 지원하는 데이터 웨어하우스의 특성으로 적절한 것은?', ['주제 중심·통합·시계열·비휘발성','실시간 개별 거래의 수정·삭제에 최적화','데이터를 부서별로 반드시 분리 저장','일시적인 데이터만 저장'], 'Inmon이 제시한 DW의 특성은 주제 중심성, 통합성, 시계열성, 비휘발성이다. 일상 거래 처리는 주로 OLTP의 역할이다.');
add(50,1,'SECI','숙련자가 작업 요령을 문서로 정리해 팀에 전달했다. 지식 전환의 유형은?', ['외재화: 암묵지 → 형식지','공통화: 암묵지 → 암묵지','연결화: 형식지 → 형식지','내재화: 형식지 → 암묵지'], '말로 설명하기 어려운 경험과 노하우를 문서 등 명시적 지식으로 표현하는 것은 외재화다. 문서를 읽고 실제 경험으로 체득하는 과정은 내재화다.');
add(50,1,'데이터베이스','같은 고객 정보를 영업팀과 서비스팀이 함께 사용할 수 있다. 이 사례에 가장 가까운 데이터베이스의 특성은?', ['공용 데이터','휘발성 데이터','개인 전용 데이터','오직 정성적 데이터'], '데이터베이스는 여러 사용자나 응용 프로그램이 공동으로 이용하는 공용 데이터다. 통합·저장·운영·공용이라는 관점으로 정리할 수 있다.');
add(50,1,'빅데이터 패러다임','빅데이터 활용이 확대되면서 나타난 변화로 가장 적절한 것은?', ['사전 정제 중심에서 활용 시점의 처리 중요성 확대','표본 분석만 가능해지고 전수 분석은 불가능','상관관계를 분석에서 완전히 배제','데이터 규모와 다양성의 중요성 감소'], '전통적 접근은 목적에 맞춰 미리 정제하는 경향이 강했다. 빅데이터 환경에서는 대규모 원자료를 보유한 뒤 목적에 따라 처리하는 접근과 전수 분석·상관관계 탐색의 활용이 커졌다.');
add(50,1,'유전자 알고리즘','선택, 교차, 돌연변이를 반복해 좋은 해를 탐색하는 기법은?', ['유전자 알고리즘','선형회귀','주성분 분석','단순 임의 추출'], '유전자 알고리즘은 자연선택과 유전의 원리를 모방한 탐색·최적화 방법이다. 적합도가 높은 개체를 선택하고 교차와 돌연변이로 다음 세대를 생성한다.');
add(50,1,'회귀 활용','주택 면적과 건축 연수를 이용해 주택 가격이라는 연속값을 예측하려 한다. 가장 직접적인 분석은?', ['회귀분석','연관규칙 분석','소셜 네트워크 분석','군집의 개수만 계산'], '연속형 목표값을 설명하거나 예측하는 문제에는 회귀분석을 적용할 수 있다. 범주를 예측하는 분류와 구분한다.');
add(50,1,'소셜 네트워크','사용자 간의 팔로우 관계에서 연결 구조와 영향력이 큰 사용자를 찾는 분석은?', ['소셜 네트워크 분석','분산분석','계절 차분','단순 데이터 정렬'], '소셜 네트워크 분석은 노드와 연결선으로 관계를 표현하고 중심성·연결 구조 등을 분석한다. 연결 중심성, 매개 중심성 등은 서로 다른 영향력 관점이다.');
add(50,1,'MapReduce','분산 처리에서 Map 단계가 출력한 동일 키의 값들을 모아 합계로 집계하는 단계는?', ['Reduce','데이터 라벨링','모델 검증','Min-max 정규화'], 'Map은 입력을 키-값 형태의 중간 결과로 처리한다. Shuffle로 동일 키를 모은 뒤 Reduce에서 집계·병합한다. 단어 빈도 계산은 대표 예시다.');
add(50,1,'CRM·SCM','고객 구매 이력을 바탕으로 개인화 캠페인을 기획하는 시스템과 공급·생산·물류 흐름을 관리하는 시스템의 조합은?', ['CRM, SCM','SCM, CRM','OLAP, PCA','DBSCAN, ERP'], 'CRM은 고객 관계 관리, SCM은 공급망 관리다. 고객 유지와 개인화는 CRM, 조달·생산·물류의 통합 관리는 SCM에 가깝다.');
add(50,1,'소프트 스킬','데이터 사이언티스트의 소프트 스킬에 가장 가까운 역량은?', ['분석 결과를 이해관계자에게 설득력 있게 설명','분산 처리 시스템 구현','통계 추정량 계산','프로그래밍 언어 문법 숙달'], '소프트 스킬에는 의사소통, 협업, 비판적 사고, 비즈니스에 대한 이해 등이 포함된다. 통계·코딩·처리 기술은 하드 스킬에 해당한다.');
add(50,2,'데이터 유형','필드 구조를 태그로 표현하지만 관계형 테이블처럼 고정된 스키마를 요구하지 않는 XML 문서는?', ['반정형 데이터','비정형 데이터만 해당','정형 데이터만 해당','수치형 데이터만 해당'], 'XML·JSON은 자체 구조나 메타데이터를 포함하는 반정형 데이터의 대표 예다. 표 형태의 고정 스키마는 정형, 음성·자유 문서는 비정형에 가깝다.');
add(50,2,'분석 수준 진단','분석 준비도와 분석 성숙도가 모두 낮은 조직에 해당하는 진단 유형은?', ['준비형','정착형','확산형','도입형'], '준비형은 준비도와 성숙도가 모두 낮다. 준비도 높음·성숙도 낮음은 도입형, 준비도 낮음·성숙도 높음은 정착형, 둘 다 높음은 확산형이다.');
add(50,2,'CRISP-DM 모델링','CRISP-DM에서 모델링 단계의 활동으로 가장 적절한 것은?', ['기법 선택, 테스트 설계, 모델 구축과 기술적 평가','사업 목표와 성공 기준만 정의','운영 환경에 결과를 배포','사업 목적의 충족 여부를 최종 검토'], '모델링에서는 분석 기법을 선정하고 검증 설계를 만든 뒤 모델을 구축·평가한다. 이후 평가 단계에서는 비즈니스 목표 달성 여부와 다음 단계를 검토한다.');
add(50,2,'CRISP-DM 평가','모델의 정확도는 높지만 실제 사업 목적과 맞지 않는다. 이를 검토하고 배포 여부를 결정하는 단계는?', ['평가(Evaluation)','데이터 수집','데이터 준비','업무 이해만으로 종료'], '평가는 기술적 성능뿐 아니라 비즈니스 목표 충족 여부와 프로세스의 누락을 검토한다. 모델링 단계의 모델 성능 평가와 사업 관점의 평가를 구분해야 한다.');
add(50,3,'모집단·표본','전체 고객의 평균 구매액 μ를 추정하기 위해 200명을 조사해 표본평균 x̄를 계산했다. 올바른 설명은?', ['μ는 모수, x̄는 통계량','μ는 통계량, x̄는 모수','둘 다 반드시 모수','둘 다 모집단의 크기'], '모수는 모집단의 특성을 나타내며, 통계량은 표본에서 계산한다. 표본평균은 모집단 평균을 추정하기 위한 통계량이다.');
add(50,3,'공분산','독립인 두 확률변수 X, Y가 유한한 분산을 가진다. 반드시 성립하는 것은?', ['Cov(X,Y)=0','Corr(X,Y)=1','X=Y','Cov(X,Y)>0'], '독립이면 E[XY]=E[X]E[Y]이므로 공분산은 0이다. 반대로 공분산이 0이라는 사실만으로 일반적으로 독립을 결론낼 수는 없다. 상관계수는 분산이 양수일 때 정의된다.');
add(50,3,'나무 정지규칙','의사결정나무를 지나치게 깊게 성장시키는 것을 막는 사전 정지규칙은?', ['최대 깊이와 최소 노드 표본 수 설정','모든 말단 노드가 순수해질 때까지 무조건 분할','시험 데이터의 정답을 분할 기준에 포함','훈련 오차가 0이 되도록 깊이 제한 제거'], '최대 깊이, 최소 분할 표본 수 등의 조건은 나무 성장을 제한하는 사전 가지치기다. 충분히 성장한 뒤 불필요한 가지를 제거하는 사후 가지치기와 구분한다.');
add(50,3,'데이터 분할','훈련·검증·시험 데이터의 용도를 바르게 연결한 것은?', ['모수 학습 · 하이퍼파라미터 선택 · 최종 성능 평가','최종 성능 평가 · 모수 학습 · 하이퍼파라미터 선택','하이퍼파라미터 선택 · 최종 성능 평가 · 모수 학습','세 데이터 모두 최종 모델 선택에 반복 사용'], '훈련 데이터로 모델을 학습하고 검증 데이터로 설정을 선택한다. 시험 데이터는 최종 평가용으로 남겨 두어야 하며, 반복적으로 선택에 쓰면 성능 추정이 낙관적으로 편향된다.');
add(50,3,'이항 확률','공정한 동전을 독립적으로 5번 던졌다. 모두 앞면일 확률은?', ['1/32','1/5','1/10','1/16'], '각 시행에서 앞면 확률은 1/2이다. 독립 시행이므로 (1/2)^5=1/32=0.03125다.');
add(50,3,'가설검정','H₀: 앞면 확률=0.5, H₁: 앞면 확률>0.5인 단측 검정에서 5번 모두 앞면이었다. 정확 이항 검정의 p값과 유의수준 0.05에서의 판단은?', ['p=0.03125, H₀ 기각','p=0.0625, H₀ 기각','p=0.5, H₀ 기각','p=0.03125, H₀ 기각 불가'], '단측 대립가설 방향에서 관측치 이상으로 극단적인 사건은 5번 모두 앞면이다. p=(1/2)^5=0.03125<0.05이므로 기각한다. 양측 검정이라면 p=0.0625로 판단이 달라진다.');
add(50,3,'소량 데이터','표본이 적은 상황에서 모델 평가의 변동성을 줄이고 데이터를 효율적으로 활용하는 방법은?', ['교차 검증을 사용하되 데이터 누수를 방지','시험 데이터를 여러 번 복제해 훈련에 포함','복잡도를 제한하지 않고 훈련 오차만 최소화','목표값을 특징 변수로 넣어 학습'], '교차 검증은 여러 분할에서 성능을 평가한다. 전처리·특징 선택도 각 훈련 폴드 안에서 수행해야 누수를 막을 수 있다. 표본 복제는 새로운 정보를 만들어 주지 않는다.');
add(50,3,'tanh','활성화 함수 tanh(x)에 대한 설명으로 옳은 것은?', ['출력 범위는 (-1,1), tanh(0)=0','출력 범위는 (0,1), tanh(0)=0.5','음수 입력은 항상 0으로 변환','x의 크기와 관계없이 기울기는 항상 1'], 'tanh는 0을 중심으로 하는 S자 함수이며 유한한 입력의 출력은 -1과 1 사이다. 양 끝에서 포화되므로 깊은 신경망에서는 기울기 소실이 발생할 수 있다.');
add(50,3,'오분류율','다음 이진 분류 결과의 오분류율은?', ['0.15','0.85','0.10','0.20'], '오분류율=(FP+FN)/전체=(10+20)/200=0.15다. 정확도는 (TP+TN)/전체=0.85이며 두 값의 합은 1이다.', 'TP=70, FN=20, FP=10, TN=100');
add(50,3,'민감도','다음 결과에서 민감도(재현율)는?', ['0.8','0.6','0.75','0.9'], '민감도=TP/(TP+FN)=60/(60+15)=0.8이다. 정밀도는 TP/(TP+FP)=60/100=0.6으로 분모가 다르다.', 'TP=60, FN=15, FP=40, TN=85');
add(50,3,'연관규칙 지지도','전체 250건의 거래 중 차와 쿠키를 함께 산 거래가 50건이다. 규칙 “차 → 쿠키”의 지지도는?', ['0.20','0.50','0.25','0.80'], '지지도는 두 품목이 동시에 나타난 거래의 비율이다. P(차∩쿠키)=50/250=0.20이다.');
add(50,3,'연관규칙 신뢰도','차를 구매한 거래가 80건이며, 그중 쿠키도 구매한 거래가 48건이다. “차 → 쿠키”의 신뢰도는?', ['0.60','0.48','0.80','1.67'], '신뢰도는 선행 품목 구매 조건에서 후행 품목도 구매할 조건부 확률이다. P(쿠키|차)=48/80=0.60이다. 규칙의 방향을 바꾸면 값이 달라질 수 있다.');
add(50,3,'DBSCAN','DBSCAN의 장점으로 적절한 것은?', ['임의 모양의 밀집 군집과 잡음을 구분할 수 있다','군집 수 K를 반드시 미리 지정한다','모든 군집이 구형이어야 한다','거리를 전혀 사용하지 않는다'], 'DBSCAN은 ε 이웃과 최소 표본 수를 이용한 밀도 기반 군집 방법이다. 군집 수를 직접 지정하지 않으며 비구형 군집과 잡음을 찾을 수 있지만 서로 다른 밀도에는 민감할 수 있다.');
add(50,3,'DBSCAN 핵심점','ε 이웃의 점 수가 자기 자신을 포함해 6개이고 MinPts=5이다. 이 점은?', ['핵심점(core point)','항상 잡음점','반드시 경계점','군집의 중심점이라는 뜻의 평균'], '자신을 포함하는 이웃 수 기준이 MinPts 이상이면 핵심점이다. 경계점은 스스로 핵심점 조건을 만족하지 않지만 핵심점의 이웃에 있는 점이다.');
add(50,3,'PCA','주성분 분석(PCA)에 대한 설명으로 옳은 것은?', ['원래 변수의 선형결합으로 분산을 크게 설명하는 축을 찾는다','종속변수의 정답을 반드시 이용한다','모든 주성분은 원래 변수 하나와 정확히 동일하다','첫 주성분은 항상 분산이 가장 작다'], 'PCA는 비지도 차원 축소 방법이다. 첫 주성분은 최대 분산을 설명하며 이후 주성분은 앞선 주성분과 직교한다. 변수의 단위가 다르면 표준화 여부를 검토한다.');
// 49회: 35문항, 공개 복원 학습 정리의 주제를 바탕으로 재구성
add(49,1,'DW·DM','전사 데이터 웨어하우스와 특정 부서용 데이터 마트의 관계로 가장 적절한 것은?', ['데이터 마트는 특정 업무·부서의 분석 목적에 집중한다','데이터 마트는 항상 전사 DW보다 범위가 넓다','DW는 거래 처리만, DM은 백업만 담당한다','DW와 DM은 물리적으로 반드시 같은 테이블이다'], '데이터 마트는 특정 부서나 주제의 분석에 초점을 둔다. 전사 DW에서 구축할 수도 있으며 독립적으로 구축하는 접근도 있다.');
add(49,1,'OLTP·OLAP','“상품 주문을 즉시 등록”과 “지역별 3년간 매출을 다차원 분석”에 각각 적합한 방식은?', ['OLTP, OLAP','OLAP, OLTP','PCA, OLTP','둘 다 DBSCAN'], 'OLTP는 일상적인 거래 처리, OLAP은 의사결정용 다차원 분석에 초점을 둔다. 처리 목적과 접근 패턴의 차이를 이해해야 한다.');
add(49,1,'데이터 단위','10진 접두어 기준 데이터 크기를 작은 것부터 바르게 나열한 것은?', ['PB → EB → ZB → YB','EB → PB → YB → ZB','PB → ZB → EB → YB','YB → ZB → EB → PB'], '10진 기준 Peta=10^15, Exa=10^18, Zetta=10^21, Yotta=10^24이다. PiB 등 2진 접두어와 혼동하지 않는다.');
add(49,1,'빅데이터 위기','자동 추천 모델이 특정 집단을 지속적으로 불리하게 평가한다. 가장 적절한 대응은?', ['데이터와 결과의 편향을 점검하고 설명·책임 체계를 마련','분석 결과를 무조건 객관적 사실로 간주','모델의 기준과 검증 절차를 완전히 비공개로 유지','표본 수를 늘리기만 하면 편향은 반드시 사라진다고 판단'], '빅데이터 활용에는 편향·사생활 침해·책임성·데이터 오용 등의 위험이 있다. 데이터 규모만으로 문제를 해결할 수 없으며 검증과 책임 체계가 필요하다.');
add(49,1,'DB 특성','데이터베이스를 “통합된 데이터”라고 설명하는 이유에 가장 가까운 것은?', ['동일한 데이터의 불필요한 중복을 줄여 일관되게 관리','모든 데이터를 반드시 한 파일에 저장','서로 관련 없는 데이터만 수집','사용자마다 같은 데이터를 별도로 복제'], '통합 데이터는 자료를 한데 모으면서 중복을 최소화하고 일관되게 관리한다는 뜻이다. 물리적으로 파일이나 서버가 하나여야 한다는 의미는 아니다.');
add(49,2,'분석 플랫폼','분석 플랫폼을 넓은 의미에서 설명한 것은?', ['데이터·기술·서비스와 사용자 생태계의 공통 기반','통계 프로그램 한 개의 실행 파일만 의미','시각화 결과를 인쇄한 종이','데이터를 사용하지 않는 조직도'], '광의의 플랫폼은 공통 자원과 서비스를 제공해 참여자와 활동을 연결하는 기반이다. 협의로는 분석에 필요한 기술·도구의 기반을 지칭할 수 있다.');
add(49,2,'마스터플랜','개별 분석 과제 기획과 분석 마스터플랜을 바르게 구분한 것은?', ['마스터플랜은 과제의 우선순위와 중장기 추진 로드맵을 다룬다','마스터플랜은 단일 모델의 계수만 추정한다','개별 과제는 반드시 전략과 무관해야 한다','둘 다 이미 끝난 분석 결과의 보관만 담당한다'], '개별 과제 기획은 구체적인 문제·목표·방법·데이터를 정의한다. 마스터플랜은 여러 과제를 종합해 전략과 우선순위, 단계별 추진 계획을 수립한다.');
add(49,2,'디자인 씽킹','사용자 공감 → 문제 정의 → 아이디어 도출 → 프로토타입 → 테스트를 반복하는 접근은?', ['디자인 씽킹','최소제곱 추정','계절 분해','단순 선형회귀'], '디자인 씽킹은 사용자 관점에서 문제를 이해하고 실험·피드백을 반복해 해법을 구체화한다. 필요에 따라 이전 단계로 돌아가는 반복적 과정이다.');
add(49,2,'상향식 접근','명확한 업무 문제가 아직 정해지지 않은 상태에서 데이터를 탐색해 잠재적인 분석 과제를 발견했다. 해당 접근은?', ['상향식 접근','하향식 접근만 해당','운영 배포','가설을 확정한 뒤 검정만 수행'], '상향식은 데이터와 관찰로부터 패턴·문제·기회를 발견하는 접근이다. 하향식은 정의된 문제에서 출발해 해결 방안을 찾는 접근에 가깝다.');
add(49,2,'하향식 접근','하향식 분석 과제 도출 과정의 올바른 순서는?', ['문제 탐색 → 문제 정의 → 해결 방안 탐색 → 타당성 검토','모델 배포 → 데이터 폐기 → 문제 탐색 → 회계 감사','타당성 검토 → 배포 → 목표 삭제 → 데이터 수집','군집 수 결정 → 분할 → 모델링 → 공감'], '하향식은 비즈니스 문제를 탐색·정의하고 해결 방안을 찾은 뒤 타당성을 검토한다. 방법을 먼저 결정한 후 문제를 억지로 맞추지 않도록 유의한다.');
add(49,2,'나선형 모델','반복 주기마다 위험을 분석하며 계획·개발·평가를 수행하는 방법론은?', ['나선형 모델','단방향 폭포수만 해당','OLS 회귀','정적 보고서'], '나선형 모델은 반복 개발과 위험 분석을 결합한 접근이다. 매 주기 위험과 대안을 점검한다는 점이 핵심이다.');
add(49,2,'분석 조직','현업 부서에 분석 인력을 배치하면서 중앙 조직이 표준과 협업을 지원하는 방식에 가까운 것은?', ['분산형 분석 조직','모든 분석 인력을 한 중앙 부서에만 모은 집중형','분석 기능을 전부 외부에 삭제','자료 접근을 누구에게도 허용하지 않는 조직'], '분산형에서는 분석 인력이 현업과 가까이 배치되어 업무에 적용한다. 집중형·기능형과 비교할 때 현업 적용성, 중복 작업, 표준 관리 등의 장단점을 고려한다.');
add(49,2,'분석 유형','분석 대상은 명확하지만 사용할 방법은 아직 모르는 경우의 유형은?', ['솔루션(Solution)','최적화(Optimization)','발견(Discovery)','통찰(Insight)'], '대상·방법 모두 알면 최적화, 대상 알고 방법 모르면 솔루션, 대상 모르고 방법 알면 통찰, 둘 다 모르면 발견이다.');
add(49,3,'PDF·PMF','연속형 확률변수 X의 밀도 f에 대한 올바른 설명은?', ['구간 확률은 밀도를 해당 구간에서 적분해 구한다','f(x)는 모든 지점에서 반드시 1 이하','P(X=x)=f(x)가 항상 성립','밀도의 전체 적분값은 반드시 0'], '연속형에서는 한 점의 확률이 0이고 구간 확률은 밀도의 적분이다. 밀도값 자체는 1보다 클 수 있다. 이산형의 PMF는 각 값의 확률을 나타낸다.');
add(49,3,'정상성','약정상 시계열의 조건으로 적절한 것은?', ['평균·분산이 일정하고 공분산은 시차에만 의존','평균이 매 시점 증가해야 함','분산이 시간에 비례해 커져야 함','모든 시차에서 자기상관이 반드시 0'], '약정상은 평균과 분산이 시간에 따라 일정하고 공분산이 시간 위치가 아닌 시차에만 의존하는 조건이다. 정상성은 백색잡음과 같은 뜻이 아니다.');
add(49,3,'거리 척도','두 점 (1,2), (4,6)의 유클리드 거리와 맨해튼 거리는?', ['5, 7','7, 5','25, 7','5, 25'], '유클리드 거리=√(3²+4²)=5, 맨해튼 거리=|3|+|4|=7이다. 두 거리의 정의를 구분한다.');
add(49,3,'지니 불순도','두 클래스 비율이 각각 0.5인 노드의 지니 불순도는?', ['0.5','0','1','0.25'], 'Gini=1−Σpᵢ²=1−(0.5²+0.5²)=0.5다. 순수한 노드는 0이며 이진 분류에서 최대값은 0.5다.');
add(49,3,'엔트로피','이진 분류에서 클래스가 절반씩 섞여 있다. 밑이 2인 엔트로피는?', ['1','0','0.5','2'], 'H=−Σpᵢlog₂pᵢ다. 두 클래스가 0.5씩이면 −2×0.5×(−1)=1이다. 한 클래스만 있는 순수 노드는 0이다.');
add(49,3,'박스플롯','Q1=12, Q3=20이다. 1.5×IQR 기준 이상치 경계로 올바른 것은?', ['하한 0, 상한 32','하한 4, 상한 28','하한 12, 상한 20','하한 −12, 상한 44'], 'IQR=20−12=8이다. 하한=Q1−1.5IQR=0, 상한=Q3+1.5IQR=32다. 경계 바깥의 값이 이상치 후보가 된다.');
add(49,3,'완전연결법','계층적 군집에서 완전연결법이 두 군집 간 거리로 사용하는 것은?', ['두 군집의 점 쌍 거리 중 최댓값','두 군집의 점 쌍 거리 중 최솟값','중심점의 좌표 합','표본 수의 차이만'], '완전연결법은 가장 먼 점 쌍의 거리를 사용한다. 단일연결법은 가장 가까운 점 쌍의 거리, 평균연결법은 점 쌍 거리의 평균을 사용한다.');
add(49,3,'분산분석','일원 분산분석에서 집단 간 평균제곱이 18, 집단 내 평균제곱이 6일 때 F 통계량은?', ['3','12','24','0.333'], 'F=MS_between/MS_within=18/6=3이다. F 검정은 집단 간 변동을 집단 내 변동과 비교한다. 유의성을 판단하려면 자유도와 기준도 필요하다.');
add(49,3,'MDS','객체 간 거리 정보를 최대한 보존하도록 저차원 공간에 객체를 배치하는 기법은?', ['다차원 척도법(MDS)','Apriori','로지스틱 회귀','시계열 차분'], 'MDS는 객체 사이의 유사도·거리 관계를 저차원 좌표로 표현한다. PCA의 분산 보존 목적과 구분해 이해한다.');
add(49,3,'SVM 커널','SVM에서 커널 함수를 쓰는 주된 목적은?', ['명시적 고차원 변환 없이 특징 공간의 내적을 계산','종속변수 라벨을 제거','훈련 데이터의 개수를 무조건 줄임','모든 분류 경계를 원래 공간의 직선으로 제한'], '커널 트릭은 고차원 특징 공간의 내적을 직접 계산한다. 이를 통해 원래 공간에서 비선형인 결정 경계를 표현할 수 있다.');
add(49,3,'왜도','대부분의 값은 작지만 일부 매우 큰 값 때문에 오른쪽 꼬리가 길다. 일반적인 왜도 방향은?', ['양의 왜도','음의 왜도','항상 0','표본 수와 같은 값'], '오른쪽 꼬리가 길면 양의 왜도, 왼쪽 꼬리가 길면 음의 왜도다. 평균·중앙값의 순서를 모든 분포에 절대적으로 적용하지 않도록 유의한다.');
add(49,3,'상관계수 변환','Corr(X,Y)=0.7이고 두 변수의 분산은 양수다. Corr(−2X+1,3Y−4)는?', ['−0.7','0.7','−4.2','4.2'], '상관계수는 양의 상수배와 평행이동에 변하지 않는다. 한 변수에 음의 상수를 곱하면 부호만 바뀌므로 −0.7이다.');
add(49,3,'기울기 소실','깊은 신경망에서 sigmoid를 반복 사용하면 초기 층의 학습이 느려질 수 있는 이유는?', ['역전파에서 작은 미분값이 반복 곱해져 기울기가 작아짐','모든 미분값이 항상 무한대','학습 데이터가 자동으로 사라짐','출력 노드가 입력값을 무조건 복제'], '포화 영역에서 sigmoid의 미분값은 작다. 여러 층의 미분이 곱해지면 입력에 가까운 층의 기울기가 매우 작아질 수 있다.');
add(49,3,'OLS','일반적인 선형회귀의 최소제곱법이 최소화하는 것은?', ['관측값과 예측값의 잔차 제곱합','회귀계수의 단순 합','독립변수의 표준편차','종속변수의 평균만'], 'OLS는 Σ(yᵢ−ŷᵢ)²를 최소화하는 계수를 추정한다. 잔차는 관측값에서 예측값을 뺀 값이다.');
add(49,3,'표본추출','전체 고객을 연령대별로 나눈 뒤 각 연령대 안에서 무작위로 표본을 뽑았다. 이 방법은?', ['층화추출','군집추출','판단추출','편의추출'], '층화추출은 모집단을 층으로 나누고 각 층에서 추출한다. 군집추출은 일부 군집 자체를 뽑아 그 안의 전체 또는 일부를 조사하는 방식이다.');
add(49,3,'배깅','원래 학습 자료에서 복원추출한 여러 표본으로 모델을 독립 학습한 뒤 예측을 결합하는 방법은?', ['배깅','순차 부스팅','단일 K-means','한 번의 주성분 변환'], '배깅은 bootstrap aggregating의 약자다. 여러 모델의 예측을 결합해 주로 분산을 줄이며, 이전 모델의 오차를 순차 보완하는 부스팅과 구분한다.');
add(49,3,'랜덤 포레스트','랜덤 포레스트가 일반적인 의사결정나무 배깅에 더해 사용하는 무작위성은?', ['각 분할에서 일부 특징만 후보로 고려','종속변수 정답을 무작위로 변경','시험 데이터로만 분할 기준을 계산','모든 나무에서 같은 특징만 강제로 사용'], '랜덤 포레스트는 부트스트랩 표본과 무작위 특징 부분집합을 사용해 나무 간 상관을 낮춘다. 회귀에서는 평균, 분류에서는 투표 등의 방법으로 결합한다.');
add(49,3,'결측 대치','검증 자료에 대한 정보 누수를 방지하는 올바른 평균 대치 절차는?', ['훈련 자료에서 평균을 구해 훈련·검증 자료에 적용','분할 전에 전체 자료의 평균을 계산','검증 정답을 이용해 결측값 결정','시험 자료의 평균을 훈련 단계에 사용'], '대치·표준화 등의 전처리 파라미터는 훈련 데이터에서 학습해야 한다. 검증·시험 데이터는 훈련에서 얻은 값을 그대로 적용한다.');
add(49,3,'p값','가설검정의 p값에 대한 올바른 해석은?', ['귀무가설 하에서 관측 결과 이상으로 극단적인 결과를 얻을 확률','귀무가설이 참일 사후확률','대립가설이 거짓일 확률','표본평균이 모수와 정확히 같을 확률'], 'p값은 귀무가설을 가정했을 때의 결과 극단성에 대한 확률이다. 귀무가설 자체가 참일 확률이나 효과의 크기로 해석할 수 없다.');
add(49,3,'표본·비표본오차','전체 모집단을 조사하는 전수조사에서도 발생할 수 있는 오류는?', ['질문 오해, 입력 실수 등 비표본오차','표본추출로 인한 오차만','전수조사는 모든 오류가 0','무조건 표본크기의 역수만큼 발생하는 오차'], '전수조사는 표본을 선택해서 발생하는 표본오차를 없애지만 측정·응답·처리 과정의 비표본오차는 남을 수 있다.');
add(49,3,'정밀도','양성으로 예측한 50건 중 실제 양성은 40건이다. 정밀도는?', ['0.8','0.2','1.25','0.5'], '정밀도=TP/(TP+FP)=40/50=0.8이다. 실제 양성 중 맞힌 비율인 재현율과 구분한다.');
add(49,3,'향상도','P(B)=0.25, P(B|A)=0.50이다. 규칙 A→B의 향상도와 해석은?', ['2, 함께 등장하는 경향이 독립일 때보다 큼','0.5, 양의 연관','2, 반드시 인과관계','1, 완전 독립'], 'Lift=P(B|A)/P(B)=0.50/0.25=2다. 1보다 크면 양의 연관, 1이면 독립 기준, 1보다 작으면 음의 연관이다. 연관은 인과관계를 증명하지 않는다.');
// 48회: 35문항, 복원 분석에 보고된 주제를 바탕으로 재구성
add(48,1,'정성·정량','“제품에 대한 자유로운 만족 의견”과 “구매 횟수”를 바르게 분류한 것은?', ['정성 데이터, 정량 데이터','정량 데이터, 정성 데이터','둘 다 정량 데이터만 해당','둘 다 데이터가 아님'], '의견과 설명은 정성, 수량으로 측정되는 구매 횟수는 정량 데이터다. 정성/정량 구분과 정형/비정형 구분은 서로 다른 관점이다.');
add(48,1,'DB·DBMS','데이터베이스(DB)와 DBMS를 바르게 구분한 설명은?', ['DB는 데이터의 집합, DBMS는 이를 관리하는 소프트웨어','DB는 프로그램, DBMS는 종이 문서','DBMS는 데이터 조회 기능을 제공하지 않음','DB는 오직 엑셀 파일만 의미'], 'DB는 조직화된 데이터의 집합이며 DBMS는 정의·저장·조회·변경·권한 등을 관리하는 소프트웨어다.');
add(48,1,'SECI 내재화','직원이 매뉴얼을 읽고 반복 실습해 업무를 몸에 익혔다. 이 전환 과정은?', ['내재화: 형식지 → 암묵지','외재화: 암묵지 → 형식지','연결화: 형식지 → 형식지','공통화: 암묵지 → 암묵지'], '문서화된 형식지를 개인 경험과 실습을 통해 암묵지로 체득하는 것은 내재화다. 연결화는 여러 명시적 지식을 결합하는 과정이다.');
add(48,1,'빅데이터 자원','빅데이터 활용을 위한 핵심 자원 조합으로 가장 적절한 것은?', ['데이터, 기술, 인력','로고, 명함, 사무실 색상','통계 프로그램만','파일 용량만'], '데이터를 확보하는 것만으로 가치를 창출할 수 없다. 처리·분석 기술과 이를 해석하고 업무에 적용할 인력이 함께 필요하다.');
add(48,1,'알고리즈미스트','알고리즈미스트의 역할에 가장 가까운 것은?', ['알고리즘의 오류·편향과 부당한 피해를 점검','서버 용량만 구매','회계 장부만 작성','데이터 저장을 무조건 금지'], '알고리즈미스트는 알고리즘 기반 의사결정의 공정성·책임성을 점검하는 관점에서 등장한 역할이다. 분석·모델 개발 중심의 데이터 사이언티스트와 역할 초점이 다르다.');
add(48,1,'가치 패러다임','데이터 가치 활용의 패러다임을 디지털화 이후의 순서로 바르게 나열한 것은?', ['연결(Connection) → 에이전시(Agency)','에이전시 → 연결','데이터 삭제 → 수기 기록','분산분석 → 회귀분석'], '디지털화는 정보를 디지털로 전환하고, 연결은 사람·사물·정보를 연결한다. 에이전시는 연결된 데이터를 이용해 기기나 서비스가 사용자의 목적을 대신 수행하는 방향이다.');
add(48,1,'빅데이터 위험','빅데이터 분석 결과를 확률적 예측이 아닌 개인의 미래 행동에 대한 확정 사실처럼 사용했다. 관련 위험은?', ['책임 원칙 훼손과 데이터 오용','데이터 저장 비용 감소','분산 처리 효율 향상','샘플링 오차의 자동 소멸'], '확률적 예측을 근거로 개인에게 부당한 책임을 부과하거나 불이익을 줄 수 있다. 예측의 불확실성을 이해하고 적절한 검증·책임 기준을 마련해야 한다.');
add(48,2,'최적화 유형','분석 대상과 적용할 분석 방법을 모두 알고 있을 때의 과제 유형은?', ['최적화','발견','통찰','솔루션'], '대상과 방법을 모두 알고 있으면 최적화다. 무엇을 분석할지와 어떻게 분석할지를 두 축으로 유형을 구분한다.');
add(48,2,'CRISP-DM 준비','결측값 처리와 분석용 테이블 구성을 주로 수행하는 CRISP-DM 단계는?', ['데이터 준비','사업 이해','배포','프로젝트 최종 종료'], '데이터 준비는 선택·정제·구성·통합·형식화 등을 포함한다. 데이터 이해 단계는 수집한 자료를 탐색하고 품질을 점검하는 데 초점을 둔다.');
add(48,2,'상향식·비지도','정답 라벨이 없는 고객 데이터를 탐색해 새로운 고객 유형을 발견하려 한다. 적절한 조합은?', ['상향식 접근과 군집분석','시험 자료 정답을 이용한 지도학습','개별 거래 등록만 반복','목표를 삭제하고 데이터도 삭제'], '상향식 탐색에서 비지도학습은 사전에 정의되지 않은 패턴과 유형을 발견하는 데 활용된다. 군집분석은 라벨 없이 유사한 고객들을 묶을 수 있다.');
add(48,2,'데이터 품질','동일 고객의 생년월일이 여러 시스템에서 서로 다르다. 직접적으로 문제가 되는 품질 차원은?', ['일관성','시각적 아름다움','압축률','파일 확장자 길이'], '일관성은 같은 정보가 시스템·규칙 사이에서 모순되지 않는 성질이다. 정확성, 완전성, 적시성 등과 함께 데이터 품질을 점검한다.');
add(48,2,'과제 우선순위','분석 과제의 시급성과 난이도를 판단할 때의 설명으로 적절한 것은?', ['시급성은 사업적 필요·효과, 난이도는 기술·자원 제약과 관련','시급성은 코드 줄 수만으로 결정','난이도는 기대 수익만으로 결정','둘 다 표본 평균만으로 결정'], '시급성은 전략적 필요성과 가치에, 난이도는 데이터 확보·기술 수준·자원 등에 영향을 받는다. 우선순위는 조직의 전략과 실행 여건을 함께 고려한다.');
add(48,2,'분석 성숙도','분석 성숙도 진단에서 분석이 조직 전반의 의사결정과 업무에 내재화되어 활용되는 정도를 보는 것은?', ['분석 활용의 발전 수준','보유한 파일 이름의 개수','직원의 나이만','서버 제조사만'], '성숙도는 분석 도입부터 활용의 발전 정도를 본다. 준비도는 분석을 수행할 업무·인력·데이터·인프라 등의 기반을 점검하는 관점이다.');
add(48,2,'로드맵','분석 마스터플랜의 로드맵에 포함할 내용으로 적절한 것은?', ['과제별 추진 순서, 기간, 연계 관계와 자원 계획','확정되지 않은 모델 계수를 전사 전략으로 고정','모든 과제를 같은 날 무조건 완료','사업 목표를 기록에서 제외'], '로드맵은 과제를 단계별로 언제, 어떤 의존 관계와 자원으로 실행할지 정리한다. 데이터·인프라 등의 선행 조건도 고려한다.');
add(48,2,'집중형 조직','분석 전문 인력을 중앙 전담 조직에 모아 현업 분석을 지원하는 형태는?', ['집중형','현업에만 각각 배치하는 분산형','분석 업무가 없는 조직','모든 부서를 해산한 조직'], '집중형은 전문 역량과 표준을 중앙에 모을 수 있다. 현업의 요구와 거리가 생기거나 병목이 발생할 수 있으므로 협업 구조가 중요하다.');
add(48,2,'분석 거버넌스','분석 거버넌스에 대한 설명으로 적절한 것은?', ['조직·프로세스·표준·데이터·인프라와 성과 관리 체계','모델 정확도 하나만으로 모든 운영을 결정','데이터 책임자와 권한은 불필요','분석 도구의 색상 설정만 의미'], '분석 거버넌스는 분석을 지속적으로 실행·관리하기 위한 조직적 체계다. 표준, 역할, 품질, 보안, 인프라, 성과 등의 관리 요소를 포함한다.');
add(48,3,'통계적 추론','일부 유권자 조사로 전체 유권자의 지지율과 불확실성을 추정했다. 이 과정은?', ['추론통계','기술통계만 수행','데이터 압축','중복 제거만 수행'], '추론통계는 표본을 이용해 모집단의 특성을 추정하거나 가설을 검정한다. 기술통계는 관측된 자료 자체를 요약한다.');
add(48,3,'다중공선성','다중회귀의 독립변수 사이에 매우 강한 선형 관계가 있다. 주로 나타나는 문제는?', ['계수 추정의 분산이 커지고 해석이 불안정해짐','잔차가 반드시 0이 됨','모든 회귀계수가 반드시 1로 고정','종속변수가 자동으로 범주형으로 변환'], '다중공선성은 계수 추정의 불확실성과 민감도를 높인다. 변수 선택·결합, 규제 등을 검토하며 VIF 같은 지표를 참고할 수 있다.');
add(48,3,'측정 척도','섭씨온도처럼 값의 차이는 의미 있지만 절대적인 0이 없어 비율은 직접 해석하기 어려운 척도는?', ['등간척도','명목척도','서열척도','비율척도'], '등간척도는 간격의 의미가 있으나 절대 0이 없다. 섭씨 20도가 10도보다 두 배 뜨겁다고 해석할 수 없다. 비율척도는 절대 0을 갖는다.');
add(48,3,'제1종 오류','실제로 참인 귀무가설을 기각하는 오류는?', ['제1종 오류','제2종 오류','검정력','정확한 판단'], '제1종 오류는 참인 귀무가설을 기각하는 경우이고, 그 확률을 유의수준 α로 통제한다. 제2종 오류는 거짓인 귀무가설을 기각하지 않는 경우다.');
add(48,3,'교차분석','성별과 구매 여부라는 두 범주형 변수의 독립성을 검정하려 한다. 기대빈도 조건이 충분할 때 사용할 수 있는 검정은?', ['카이제곱 독립성 검정','단일 표본 평균 t검정','PCA 고유값 검정','단순 시계열 차분'], '분할표의 관측빈도와 독립을 가정한 기대빈도를 비교한다. 작은 기대빈도에서는 정확 검정 등 다른 방법을 검토할 수 있다.');
add(48,3,'회귀 잔차','잔차 대 예측값 그래프에 뚜렷한 곡선 패턴이 있다. 우선 검토할 내용은?', ['선형 모형이 비선형 관계를 충분히 반영했는지','모든 오차가 독립이라는 확정 결론','다중공선성이 반드시 없다는 결론','원자료의 삭제 없이 검토할 것이 없음'], '곡선 패턴은 모형의 선형 관계 가정이나 함수 형태가 부적절할 가능성을 시사한다. 잔차가 무작위로 퍼지는지 살펴보고 변환이나 비선형 항 등을 검토한다.');
add(48,3,'신뢰구간','빈도주의의 95% 신뢰구간을 정확히 해석한 것은?', ['동일 절차를 반복하면 계산된 구간의 약 95%가 참 모수를 포함','이번에 구한 고정 구간에 모수가 있을 확률이 반드시 95%','표본 데이터 95%가 구간에 반드시 포함','모든 미래 관측값 95%를 포함하는 예측구간과 동일'], '모수는 고정이고 표본에 따라 구간이 변한다. 95%는 반복 표본추출 과정에서의 포함 비율을 뜻하며 개별 구간은 모수를 포함하거나 포함하지 않는다.');
add(48,3,'t검정 출력','독립 두 집단 평균 차이 검정의 p값이 0.018이다. 유의수준 0.05에서 적절한 판단은?', ['평균이 같다는 귀무가설을 기각','평균 차이가 없음을 증명','차이의 크기가 반드시 실무적으로 큼','귀무가설이 참일 확률이 1.8%'], 'p<α이므로 귀무가설을 기각한다. 통계적 유의성은 효과의 크기나 실무적 중요성을 보장하지 않으며 신뢰구간과 효과 크기를 함께 검토한다.');
add(48,3,'PCA 설명분산','PCA의 고유값이 4, 2, 1, 1이다. 앞의 두 주성분의 누적 설명분산 비율은?', ['75%','50%','60%','87.5%'], '총 분산은 고유값의 합 8이다. 첫 두 주성분의 합은 6이므로 6/8=0.75, 즉 75%다.');
add(48,3,'회귀 유의성','절편을 포함한 다중회귀의 전체 F 검정에서 검정하는 귀무가설은?', ['모든 기울기 계수가 0이다','절편이 반드시 1이다','모든 독립변수가 서로 독립이다','잔차의 모든 값이 0이다'], '전체 F 검정은 절편을 제외한 기울기 계수들이 모두 0인지 검정한다. 개별 계수의 유의성은 다른 변수를 통제한 t검정 등으로 본다.');
add(48,3,'로짓·시그모이드','로지스틱 회귀에서 p=1/(1+e⁻ᶻ)이고 z=0일 때 p와 logit(p)는?', ['0.5, 0','0, 0.5','1, 1','0.5, 1'], 'sigmoid(0)=1/(1+1)=0.5이며 logit(p)=ln(p/(1−p))이므로 logit(0.5)=ln(1)=0이다.');
add(48,3,'시계열 차분','시계열 값이 12, 15, 14, 20일 때 1차 차분은?', ['3, −1, 6','12, 27, 29, 34','−3, 1, −6','15, 14, 20'], '1차 차분은 Δyₜ=yₜ−yₜ₋₁이다. 15−12=3, 14−15=−1, 20−14=6이다. 추세 완화에 사용할 수 있지만 정상성을 무조건 보장하지는 않는다.');
add(48,3,'시계열 요소','매년 여름에 반복되는 아이스크림 판매 증가에 해당하는 요소는?', ['계절요인','불규칙요인만','추세요인만','비표본오차'], '계절요인은 일정한 달력 주기로 반복되는 패턴이다. 추세는 장기 방향, 순환은 일정하지 않은 장기 주기의 변동, 불규칙은 나머지 우연 변동에 해당한다.');
add(48,3,'마할라노비스 거리','변수 간 상관관계와 서로 다른 분산을 함께 고려하는 거리는?', ['마할라노비스 거리','맨해튼 거리만','단순 해밍 거리','좌표 차이의 부호만'], '마할라노비스 거리는 공분산 행렬의 역행렬로 차이를 가중한다. 상관과 척도를 반영하지만 공분산 행렬의 추정과 가역성을 고려해야 한다.');
add(48,3,'F1 점수','정밀도 0.75, 재현율 0.50일 때 F1 점수는?', ['0.60','0.625','0.25','1.25'], 'F1=2PR/(P+R)=2×0.75×0.50/1.25=0.60이다. 두 지표의 산술평균이 아닌 조화평균이다.');
add(48,3,'결측 완전제거','각 변수의 결측 여부가 서로 독립이며 4개 변수 각각의 결측 확률이 0.1이다. 완전한 행으로 남을 확률은?', ['0.6561','0.9','0.6','0.0001'], '각 변수가 관측될 확률은 0.9다. 독립을 가정했으므로 네 변수가 모두 관측될 확률은 0.9⁴=0.6561이다. 독립 가정이 없으면 단순 곱으로 계산할 수 없다.');
add(48,3,'Ward 연결법','Ward 방식은 계층적 군집에서 어떤 기준으로 군집을 병합하는가?', ['군집 내 제곱합의 증가가 가장 작은 두 군집','최장 점 쌍 거리가 가장 큰 두 군집','표본 수가 항상 같은 두 군집','중심점 부호가 같은 두 군집'], 'Ward 방식은 병합에 따른 군집 내 오차 제곱합 증가를 최소화한다. 단일·완전·평균연결법의 거리 정의와 구분한다.');
add(48,3,'K-means','표준적인 K-means가 최소화하는 목적함수는?', ['각 점과 배정된 군집 중심 사이의 거리 제곱합','서로 다른 군집 중심 간 거리의 합','분류의 p값 합','결측값 개수'], 'K-means는 군집 내 제곱합을 최소화한다. 군집 수를 지정해야 하며 초기값·이상치·변수 척도에 민감할 수 있다.');
add(48,3,'연관규칙 비교','규칙 A→B와 B→A에서 반드시 같은 지표는?', ['지지도와 향상도','신뢰도만','신뢰도와 민감도','모든 지표가 항상 같음'], '지지도=P(A∩B), 향상도=P(A∩B)/(P(A)P(B))는 대칭이다. 신뢰도는 각각 P(B|A), P(A|B)이므로 일반적으로 다르다.');

const RECENT_QUESTIONS = rows.map((q,i) => {
  // 보기 위치를 순환시켜 정답 위치의 편향을 방지합니다.
  const shift = (i * 3 + Math.floor(i/4)) % 4;
  const options = q.options.map((_,j) => q.options[(j + shift) % 4]);
  return { ...q, id: `r${q.round}-${String(i+1).padStart(3,'0')}`, options, answer: (4-shift)%4, source: q.round===48 ? `r48${['a','b','c'][q.subject-1]}` : `r${q.round}`, kind: q.round===49?'복원 정리 기반 재구성':'후기 기반 재구성' };
});
// 기존 100문항의 ID와 선택지 순서를 보존해 풀이·북마크 기록을 유지한다.
const ADDED_QUESTIONS = [...ROUND_QUESTIONS_40_43,...ROUND_QUESTIONS_44_47].map((q,i)=>{
  const shift=(i*3+q.round)%4;
  return {...q,options:q.options.map((_,j)=>q.options[(j+shift)%4]),answer:(q.answer-shift+4)%4,kind:'공개 복원 분석 기반 재구성',given:q.given??''};
});
// 자료의 문항 순서와 무관하게 학습 내용을 기준으로 과목을 분류한다.
const SUBJECT_CORRECTIONS = {'r50-007':3,'r50-011':2,'r50-012':1};
export const QUESTIONS = [
  ...[...RECENT_QUESTIONS,...ADDED_QUESTIONS].map(q=>({...q,subject:SUBJECT_CORRECTIONS[q.id]??q.subject})),
  ...ROUND_SUPPLEMENTS,
];
